package app.hain.ui.pim

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.scale
import androidx.compose.ui.graphics.drawscope.translate
import androidx.compose.ui.graphics.drawscope.withTransform

/**
 * Single source of truth: `assets/mascot/v2/motion/pim_motion.json` → `geometry`
 * (generated by tools/pim_gen.py). Do not hand-tune any number here.
 * viewBox = -12 -18 144 144 → content drawn in a 144-unit box starting at (-12,-18).
 */
object PimGeometry {
    const val VIEW_BOX_X = -12f
    const val VIEW_BOX_Y = -18f
    const val VIEW_BOX_SIZE = 144f

    // svg path data, ported verbatim from pim_motion.json
    const val BODY_PATH = "M60 34 C82 34 92 52 92 76 C92 96 80 106 60 106 C40 106 28 96 28 76 C28 52 38 34 60 34 Z"
    const val STEM_PATH = "M60 42 C60 33 59.5 26 57.5 20.5"
    const val LEAF_PATH = "M57.5 20.5 C54 11 44 7.5 36.5 11.5 C38 20 48 24.5 57.5 20.5 Z"
    const val LEAF_VEIN_PATH = "M56 19.5 C51 16 45 14 40 13"

    val BODY_BOTTOM_CENTRE = Offset(x = 60f, y = 106f)
    val STEM_BASE = Offset(x = 60f, y = 36f)
    val LEAF_TIP = Offset(x = 57.5f, y = 20.5f)
    val EYE_L = Offset(x = 48.5f, y = 71f)
    val EYE_R = Offset(x = 71.5f, y = 71f)
    const val EYE_W = 7f
    const val EYE_H = 14f
    const val STROKE_W = 2.5f

    /** Default fx anchor: top-right of the head. fxX/fxY are offsets from here. */
    val FX_ANCHOR = Offset(x = 96f, y = 12f)
}

/** Pim's palette from pim_motion.json `colors` (+ dark eye from DESIGN_SYSTEM §4). */
data class PimColors(
    val body: Color,
    val leaf: Color,
    val eye: Color,
)

val LightPimColors =
    PimColors(
        body = Color(color = 0xFF7FD6A4),
        leaf = Color(color = 0xFF3FAF77),
        eye = Color(color = 0xFF1F2A2E),
    )

val DarkPimColors =
    PimColors(
        body = Color(color = 0xFF7FD6A4),
        leaf = Color(color = 0xFF3FAF77),
        eye = Color(color = 0xFF0E1513),
    )

/** The nine base states of DESIGN_SYSTEM.md §4 (drawn statically here). */
enum class PimState {
    IDLE,
    THINKING,
    LISTENING,
    SPEAKING,
    SLEEPING,
    HAPPY,
    CELEBRATE,
    ERROR,
    DOWNLOADING,
}

/** Static pose per state, from the state motions in pim_motion.json. */
fun poseFor(state: PimState): PimPose =
    when (state) {
        PimState.IDLE -> PimPose()
        PimState.THINKING -> PimPose()
        PimState.LISTENING -> PimPose(eyes = PimEyes.WIDE)
        PimState.SPEAKING -> PimPose()
        PimState.SLEEPING -> PimPose(eyes = PimEyes.CLOSED, fx = PimFx.ZZZ, fxX = 2f, fxY = -4f)
        PimState.HAPPY -> PimPose(eyes = PimEyes.HAPPY, fx = PimFx.SPARKLE)
        PimState.CELEBRATE -> PimPose(eyes = PimEyes.HAPPY, fx = PimFx.SPARKLE)
        PimState.ERROR -> PimPose(eyes = PimEyes.WIDE, fx = PimFx.DROP)
        PimState.DOWNLOADING -> PimPose()
    }

/** Eye shapes of the rig (pim_motion.json). */
enum class PimEyes { PILL, WIDE, HAPPY, CLOSED, SQUEEZE }

/** Tiny accent effects (pim_motion.json). */
enum class PimFx { NONE, ZZZ, BANG, QUESTION, SPARKLE, HEART, DROP }

/**
 * The rig parameters of DESIGN_SYSTEM.md §4 (neutral in brackets):
 * x,y (0) · sx,sy squash around bottom centre (1) · tilt around bottom centre (0°) ·
 * bend stem+leaf around stem base (0°) · leaf around stem tip (0°) · leafScale (1) ·
 * eyes (pill) · eyeH blink 0–1.1 (1) · eyeDX/DY look (0, max ±5) · eyeLS/RS (1) ·
 * fx + fxA/fxX/fxY.
 */
data class PimPose(
    val x: Float = 0f,
    val y: Float = 0f,
    val sx: Float = 1f,
    val sy: Float = 1f,
    val tilt: Float = 0f,
    val bend: Float = 0f,
    val leaf: Float = 0f,
    val leafScale: Float = 1f,
    val eyes: PimEyes = PimEyes.PILL,
    val eyeH: Float = 1f,
    val eyeDX: Float = 0f,
    val eyeDY: Float = 0f,
    val eyeLS: Float = 1f,
    val eyeRS: Float = 1f,
    val fx: PimFx = PimFx.NONE,
    val fxA: Float = 1f,
    val fxX: Float = 0f,
    val fxY: Float = 0f,
)

/** One absolute M/C/L/Z command (M/C/Z from pim_motion.json, L for fx glyphs). */
internal sealed interface PathCommand {
    data class MoveTo(
        val x: Float,
        val y: Float,
    ) : PathCommand

    data class CubicTo(
        val x1: Float,
        val y1: Float,
        val x2: Float,
        val y2: Float,
        val x3: Float,
        val y3: Float,
    ) : PathCommand

    data class LineTo(
        val x: Float,
        val y: Float,
    ) : PathCommand

    data object Close : PathCommand
}

/** Parses absolute M/C/L/Z path data (pim_motion.json + fx glyphs). */
internal fun parsePathCommands(d: String): List<PathCommand> {
    val tokens = Regex("([MZCL])|(-?\\d*\\.?\\d+)").findAll(d).map { it.value }.toList()
    val commands = mutableListOf<PathCommand>()
    var i = 0

    fun nextNumber(): Float {
        val value = tokens[i].toFloat()
        i++
        return value
    }

    while (i < tokens.size) {
        when (tokens[i]) {
            "M" -> {
                i++
                val x = nextNumber()
                val y = nextNumber()
                commands += PathCommand.MoveTo(x, y)
            }
            "C" -> {
                i++
                val x1 = nextNumber()
                val y1 = nextNumber()
                val x2 = nextNumber()
                val y2 = nextNumber()
                val x3 = nextNumber()
                val y3 = nextNumber()
                commands += PathCommand.CubicTo(x1, y1, x2, y2, x3, y3)
            }
            "L" -> {
                i++
                val x = nextNumber()
                val y = nextNumber()
                commands += PathCommand.LineTo(x, y)
            }
            "Z" -> {
                i++
                commands += PathCommand.Close
            }
            else -> error("Unexpected token in path data: ${tokens[i]}")
        }
    }
    return commands
}

/** Builds a Compose path from the parsed [commands]. */
internal fun pathOf(commands: List<PathCommand>): Path {
    val path = Path()
    commands.forEach { command ->
        when (command) {
            is PathCommand.MoveTo -> path.moveTo(command.x, command.y)
            is PathCommand.CubicTo ->
                path.cubicTo(
                    command.x1,
                    command.y1,
                    command.x2,
                    command.y2,
                    command.x3,
                    command.y3,
                )
            is PathCommand.LineTo -> path.lineTo(command.x, command.y)
            PathCommand.Close -> path.close()
        }
    }
    return path
}

internal fun svgPathToPathPublic(d: String): Path = pathOf(parsePathCommands(d))

/** Draws one Pim frame in viewBox units; the canvas fit happens in [Pim]. */
fun DrawScope.drawPim(
    pose: PimPose,
    colors: PimColors,
    showVein: Boolean,
    gloss: Boolean = false,
) {
    translate(-PimGeometry.VIEW_BOX_X, -PimGeometry.VIEW_BOX_Y) {
        // body group: squash + tilt around the bottom centre, then position offset
        withTransform({
            translate(pose.x, pose.y)
            rotate(pose.tilt, PimGeometry.BODY_BOTTOM_CENTRE)
            scale(pose.sx, pose.sy, PimGeometry.BODY_BOTTOM_CENTRE)
        }) {
            drawBodyAndEyes(pose, colors, gloss)
        }
        // stem + leaf group: bend around the stem base, leaf around its own tip
        withTransform({
            translate(pose.x, pose.y)
            rotate(pose.bend, PimGeometry.STEM_BASE)
        }) {
            drawStemAndLeaf(pose, colors, showVein)
        }
        drawFx(pose, colors)
    }
}

private fun DrawScope.drawBodyAndEyes(
    pose: PimPose,
    colors: PimColors,
    gloss: Boolean,
) {
    val body = svgPathToPathPublic(PimGeometry.BODY_PATH)
    val left = PimGeometry.EYE_L + Offset(pose.eyeDX, pose.eyeDY)
    val right = PimGeometry.EYE_R + Offset(pose.eyeDX, pose.eyeDY)
    if (gloss) {
        // T-011: glossy jelly body with white oval eyes and their soft shadow (reference 7)
        drawGlossyBody(body)
        val shadow = colors.copy(eye = GLOSSY_EYE_SHADOW)
        val white = colors.copy(eye = GLOSSY_EYE)
        drawEye(left + GLOSSY_EYE_OFFSET, pose, shadow, pose.eyeLS * GLOSSY_EYE_SCALE)
        drawEye(right + GLOSSY_EYE_OFFSET, pose, shadow, pose.eyeRS * GLOSSY_EYE_SCALE)
        drawEye(left, pose, white, pose.eyeLS * GLOSSY_EYE_SCALE)
        drawEye(right, pose, white, pose.eyeRS * GLOSSY_EYE_SCALE)
        return
    }
    drawPath(body, colors.body)
    drawEye(left, pose, colors, pose.eyeLS)
    drawEye(right, pose, colors, pose.eyeRS)
}

private fun DrawScope.drawStemAndLeaf(
    pose: PimPose,
    colors: PimColors,
    showVein: Boolean,
) {
    drawPath(
        svgPathToPathPublic(PimGeometry.STEM_PATH),
        colors.leaf,
        style = Stroke(width = PimGeometry.STROKE_W, cap = StrokeCap.Round),
    )
    withTransform({
        rotate(pose.leaf, PimGeometry.LEAF_TIP)
        scale(pose.leafScale, pose.leafScale, PimGeometry.LEAF_TIP)
    }) {
        drawPath(svgPathToPathPublic(PimGeometry.LEAF_PATH), colors.leaf)
        if (showVein) {
            drawPath(
                svgPathToPathPublic(PimGeometry.LEAF_VEIN_PATH),
                colors.eye.copy(alpha = 0.35f),
                style = Stroke(width = 1.5f, cap = StrokeCap.Round),
            )
        }
    }
}
